//! `LFM_REGISTRY` — the machine's program registry.
//!
//! A program is nothing but a vector of supplied preprocessed roots plus this
//! table's entry. Maintained exactly like `compute_static_commitments`:
//! regenerated by `cargo run --bin compute_lfm_registry --release`, pinned by
//! drift tests that run on every PR, and governed by the same standing policy
//! — **a drift failure is investigated, never re-blessed to silence the
//! test.**
//!
//! Verify-side resolution returns a hard `Err` on a missing entry. There is
//! **no runtime off-switch**: no environment variable, no feature flag, no
//! fallback that recomputes or skips. The registry check is the soundness
//! argument's first premise (see `SOUNDNESS.md`).

use stark::config::Commitment;
use stark::proof::options::ProofOptions;

use crate::tables::{bitwise, keccak_rc};

use super::airs::{BLAKE3_SLOT, ChipSet, NUM_LFM_CHIPS, blake3_chunk_rows};

use super::commit::{commit_lde_columns, group_columns, lde_columns};
use super::compiler::LfmProgram;
use super::hash::HasherKind;
use super::statement::lfm_program_id;
use super::trace::range_group;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LfmProgramKind {
    /// The Milestone-B trivial program (`programs::trivial_program`).
    TrivialV0,
    /// The Milestone-C FRI-opening verifier (`programs::fri_toy_program`).
    FriToyV0,
    /// The R1b two-permutation keccak chain (`programs::keccak_chain_program`).
    KeccakChainV0,
    /// The R1c keccak256 sponge at `programs::KECCAK_SPONGE_LEN` bytes.
    KeccakSpongeV0,
    /// The R1d scripted `DefaultTranscript` replay
    /// (`programs::transcript_replay_program`).
    TranscriptReplayV0,
    /// The R1e continuation-epoch statement bind plus Phase A
    /// (`programs::statement_replay_program`).
    StatementReplayV0,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LfmRegistryError {
    UnknownProgram {
        kind: LfmProgramKind,
        blowup_factor: u8,
    },
    /// Two or more rows claim the same `(kind, blowup_factor)`.
    ///
    /// The table's key is that pair and nothing else — not the hasher, not the
    /// chunk count — so a second row for a pair that already exists is not an
    /// alternative a caller can select. It is unreachable data, and the
    /// reachable row is whichever the generator happened to print first. See
    /// [`resolve`].
    AmbiguousProgram {
        kind: LfmProgramKind,
        blowup_factor: u8,
        rows: usize,
    },
}

/// One blessed program: its committed roots, its heights and the pieces of
/// proof shape a verifier must not read off the proof.
///
/// ★ **There is deliberately no `blake3_chunks` column**, unlike
/// [`Self::keccak_rnd_chunks`]. Every registered program is a fixture that
/// compresses a handful of blocks at most, so all six sit at the policy default
/// of ONE `LFM_BLAKE3` table, and a column that can only ever read 1 would be a
/// shape a verifier could get wrong for no reason. [`Self::artifacts`] derives
/// it, and `every_registry_entry_is_a_single_blake3_table` pins the premise.
/// Blessing a chunked program means adding the column then, alongside the row.
pub struct LfmRegistryEntry {
    pub kind: LfmProgramKind,
    pub blowup_factor: u8,
    pub roots: [Commitment; NUM_LFM_CHIPS],
    pub log_heights: [u8; NUM_LFM_CHIPS],
    /// `KECCAK_RND` instances this program is proved and verified with.
    pub keccak_rnd_chunks: usize,
    /// The `LFM_HASH` permutation this program is proved and verified under.
    ///
    /// Program shape, like the roots and the chunk count — never read off the
    /// proof. `lfm_verify` builds the AIR set with this value, and it is folded
    /// into `program_id`, so the digest and the permutation it names are
    /// computed together and cannot be paired up wrongly at verify time.
    pub hasher: HasherKind,
    /// Which hash-family chip groups this program instantiates. Program shape
    /// for the same reason and read the same way — from this entry, never from
    /// the proof. See [`ChipSet`].
    pub chip_set: ChipSet,
    pub program_id: Commitment,
}

impl LfmRegistryEntry {
    /// This entry as [`LfmArtifacts`] — the shape both verify paths read.
    ///
    /// The `LFM_BLAKE3` chunk list is DERIVED rather than stored: every
    /// registered program sits at the policy default of one table, so the
    /// committed list is exactly slot 11's own root and height. See the note on
    /// the struct for why there is no column, and
    /// `every_registry_entry_is_a_single_blake3_table` for what keeps the
    /// premise honest.
    pub fn artifacts(&self) -> LfmArtifacts {
        LfmArtifacts {
            roots: self.roots,
            log_heights: self.log_heights,
            keccak_rnd_chunks: self.keccak_rnd_chunks,
            blake3_chunk_roots: vec![self.roots[BLAKE3_SLOT]],
            blake3_chunk_log_heights: vec![self.log_heights[BLAKE3_SLOT]],
            hasher: self.hasher,
            chip_set: self.chip_set,
            program_id: self.program_id,
        }
    }
}

/// A program's committed artifacts (what a registry entry pins).
pub struct LfmArtifacts {
    pub roots: [Commitment; NUM_LFM_CHIPS],
    pub log_heights: [u8; NUM_LFM_CHIPS],
    pub keccak_rnd_chunks: usize,
    /// One preprocessed root per `LFM_BLAKE3` chunk, in chunk order — empty when
    /// the BLAKE3 family is absent.
    ///
    /// The chip's chunks are NOT interchangeable the way `KECCAK_RND`'s are:
    /// each commits its own slice of the instruction column group, so each has
    /// its own root and its own height. `blake3_chunk_roots[0]` IS
    /// `roots[BLAKE3_SLOT]` and `blake3_chunk_log_heights[0]` IS
    /// `log_heights[BLAKE3_SLOT]`, which is what makes a single-chunk program
    /// bit-identical to an unchunked one; chunks 1.. live only here and are
    /// folded into `program_id` as a tail (see
    /// [`lfm_program_id`](super::statement::lfm_program_id)).
    pub blake3_chunk_roots: Vec<Commitment>,
    /// Trace log-height of each `LFM_BLAKE3` chunk, in chunk order.
    pub blake3_chunk_log_heights: Vec<u8>,
    /// The hasher `program_id` was derived under; the prove and verify paths
    /// both take it from here rather than defaulting.
    pub hasher: HasherKind,
    /// The hash families this program instantiates, derived from its own
    /// compiled groups at bless time. See [`ChipSet`].
    pub chip_set: ChipSet,
    pub program_id: Commitment,
}

impl LfmArtifacts {
    /// `LFM_BLAKE3` instances this program COMMITS — never zero, since slot 11's
    /// group is committed even for a program that never compresses.
    ///
    /// Whether a PROOF carries them is the chip mask's decision, taken where it
    /// always was: [`ChipSet::num_airs`](super::airs::ChipSet::num_airs) gates on
    /// `blake3`, and [`LfmAirs::air_refs`](super::airs::LfmAirs::air_refs) omits
    /// the instances. That is why this reports the committed count rather than
    /// the gated one, unlike [`Self::keccak_rnd_chunks`] — `KECCAK_RND` commits
    /// nothing, so it can legitimately drop to zero instances.
    pub fn blake3_chunks(&self) -> usize {
        self.blake3_chunk_roots.len()
    }
}

/// Commits every instruction column group (plus the fixed tables) at the given
/// options and derives the program digest. Host-side, seconds — there is no
/// keygen in this framework.
///
/// What the digest binds, per slot class:
///
/// - **slots 0–9** — the program-dependent instruction column groups. Root and
///   height both vary with the program; this is the program's identity.
/// - **slot 10 (`LFM_RANGE`)** — a fixed table whose group is
///   program-independent but still committed and bound, so a change to the
///   table or to the commit pipeline moves every program digest.
/// - **slot 11 (`LFM_BLAKE3`)** — a program-dependent instruction column group
///   like slots 0–9, placed after `LFM_RANGE` so the hosted keccak family stays
///   contiguous at the end (`airs::KECCAK_RND_SLOT`). ★ It is also SPLITTABLE
///   (`chunking::Blake3Chunking`), and unlike `KECCAK_RND` it commits: a chunked
///   program's chunk 0 is what this slot holds, and chunks 1.. ride
///   [`LfmArtifacts::blake3_chunk_roots`], bound into the digest as a tail. A
///   single-chunk program — every registered one — is bit-identical to the
///   unchunked machine, which is why no blessed digest moved when chunking
///   arrived.
/// - **slots 13–14 (`KECCAK_RC`, `BITWISE`)** — same treatment as `LFM_RANGE`,
///   except their preprocessed columns are owned by `tables/`, so the roots come
///   from those modules' own `preprocessed_commitment` — which is both what the
///   AIRs are built with and what the prover recommits against. Binding them
///   means a change to either production table moves every LFM program digest;
///   that is deliberate, since those tables are now part of the machine.
/// - **slot 12 (`KECCAK_RND`)** — has no preprocessed columns at all, so there
///   is nothing to commit. Its entry stays the all-zero sentinel at height 0 and
///   binds nothing. Sound because the chip is program-independent in both
///   directions: its constraints are fixed, and its trace height is free (extra
///   rows are padding with `MU = 0`, which emits no bus tokens and satisfies
///   every constraint) — the same freedom the production VM's chips have.
///   What the entry *does* pin for this slot is `keccak_rnd_chunks`: how many
///   instances of it the proof carries. That freedom is the same freedom as the
///   height — a prover who used a different count could not forge anything,
///   only fail to balance the `Keccak` bus (too few chunks) or waste rows (too
///   many) — so pinning it is a shape decision, not a soundness gate. Pinning
///   it here keeps the verifier's AIR set derivable from the registry alone,
///   with nothing about proof shape read off the proof.
///
/// The `LFM_HASH` permutation is bound too, but not through a root: it selects
/// which chip fills the `LFM_HASH` slot, and every candidate's preprocessed
/// width is the same (the instruction group is hasher-independent), so no root
/// moves with the choice. [`build_artifacts_with_hasher`] folds the kind's tag
/// into the digest instead — measured by
/// `the_blake3_choice_moves_the_program_digest_and_no_root`.
///
/// That is a statement about the machine's *own* hash, not about the hash these
/// roots are built with. The two are separate axes and both are now named in
/// `program_id` — see [`build_artifacts_with_hasher`]. If the machine's hash
/// ever also selects the commitment scheme the roots are committed under, every
/// root above moves with it and the tag on its own stops being the whole
/// binding.
/// ★ The `LFM_HASH` permutation `LFM_REGISTRY` is blessed under.
///
/// Bound into every digest in that table — `HasherKind::as_tag` is folded into
/// `lfm_program_id` — so changing it here is a re-blessing of the whole table,
/// not a re-run. **A second hasher becomes additional ROWS, never a silent
/// replacement of these.**
///
/// ⚠ Lives here rather than in `compute_lfm_registry` because it is a property
/// of the TABLE, not of the generator, and because [`build_artifacts`] has to
/// name it: a default spelled `HasherKind::default()` is a silent global, while
/// one spelled `REGISTRY_HASHER` is a statement about registry identity that a
/// reader can check against the table.
pub const REGISTRY_HASHER: HasherKind = HasherKind::Test;

pub fn build_artifacts(program: &LfmProgram, options: &ProofOptions) -> LfmArtifacts {
    // ⛔ **DEFAULTS TO `Test`, AND MUST.** The hasher is part of program
    // IDENTITY — `HasherKind::as_tag` is folded into `lfm_program_id` — and
    // `LFM_REGISTRY` is blessed under `compute_lfm_registry`'s
    // `REGISTRY_HASHER = Test`, whose own doc calls changing it a re-blessing of
    // the whole table rather than a re-run.
    //
    // ⚠ This entry point was briefly changed to name `hash_pin::BLOCK_HASHER`,
    // to fix a real defect on the AGGREGATOR path where `lfm_prove_batched`
    // inherited a toy permutation from a defaulted build. That fix was correct
    // about the defect and wrong about its scope: it moved every registry
    // program's identity away from the blessed table, and
    // `rpo_chip_tests::the_rpo_choice_moves_the_program_digest_and_no_root`
    // asserts this function defaults to `Test` in as many words.
    //
    // ★ The block path names its hasher AT THE CALL SITE
    // ([`build_artifacts_with_hasher`]) instead. Registry programs pin a byte
    // hash on their own builders, emit no `Instr::Hash`, and never consult the
    // socket — they are correct at `Test` under every pin.
    build_artifacts_with_hasher(program, options, REGISTRY_HASHER)
}

/// [`build_artifacts`] for a program proved under an explicitly chosen
/// `LFM_HASH` permutation.
///
/// The returned artifacts carry `hasher`, and `program_id` is derived from it —
/// so the same program under two hashers is two program identities, and the
/// prove/verify paths that read `LfmArtifacts` cannot pair one hasher's digest
/// with another hasher's AIR set.
///
/// # `hasher` and the commitment hash are two axes, and both are named
///
/// `hasher` names the `LFM_HASH` chip the machine RUNS. The hash the roots below
/// are BUILT with is a different question: `commit_group` and the two
/// `preprocessed_commitment` helpers all commit through `stark`'s Merkle layer
/// under whatever [`crate::hash_pin::BLOCK_COMMITMENT_HASH`] names — BLAKE3 on
/// this branch, keccak on a `cuda` build, an algebraic hash on a branch that
/// pins one.
///
/// Both are folded into `program_id` (see [`lfm_program_id`]), which is what
/// discharges the compile-time guard this function used to carry. That guard
/// refused to compile once `stark` gained a second commitment hash, on the
/// grounds that artifacts naming one hash over roots built with another is a
/// claim nothing downstream would check. Naming the second axis is the decision
/// it was holding out for: the artifacts now say which hash built the roots, so
/// there is no unstated claim left to be wrong about.
///
/// ★ **The read has MOVED, on exactly the condition this note set.** The commit
/// helpers were hard-wired to `stark`'s default aliases, so the global const was
/// then the truthful name for their output. They are now threaded through
/// [`crate::hash_pin::BlockStarkHash`] — the block path's own configuration,
/// which a hash-comparison branch re-points without touching the workspace
/// default — and `lfm_program_id` reads `BLOCK_COMMITMENT_HASH` with them. The
/// two axes still move together, which is the property that matters; what
/// changed is that the axis they follow is the pin rather than the alias.
///
/// ⚠ Still deliberately NOT done: an `H` PARAMETER on this function. Threading
/// the helpers to a build-wide pin keeps one answer per build; a parameter would
/// reintroduce the failure this note was guarding against, artifacts naming an
/// `H` the helpers did not use.
pub fn build_artifacts_with_hasher(
    program: &LfmProgram,
    options: &ProofOptions,
    hasher: HasherKind,
) -> LfmArtifacts {
    let range = range_group();
    // Slots 0..=10 in slot order. Slot 11 (`LFM_BLAKE3`) is not here because it
    // is the CHUNKED one: it contributes one committed matrix per chunk, built
    // and absorbed after this list, which is where slot order puts it anyway.
    let groups = [
        &program.groups.const_,
        &program.groups.balu,
        &program.groups.xalu,
        &program.groups.select,
        &program.groups.bitdec,
        &program.groups.hash,
        &program.groups.keccak,
        &program.groups.lanes,
        &program.groups.hint,
        &program.groups.public,
        &range,
    ];
    let mut roots = [[0u8; 32]; NUM_LFM_CHIPS];
    let mut log_heights = [0u8; NUM_LFM_CHIPS];

    // Heights first, from the compiled groups: the LDE walk below commits them
    // and the digest binds them, so both read one derivation.
    for (i, g) in groups.iter().enumerate() {
        log_heights[i] = g.padded_rows.trailing_zeros() as u8;
    }
    // The chunk heights are arithmetic (`blake3_chunk_rows`), so they are known
    // without materializing a single chunk group. Slot 11's own entry is chunk
    // 0's — the array stays the shape a single-table program has.
    let blake3_chunk_log_heights: Vec<u8> = blake3_chunk_rows(program)
        .into_iter()
        .map(|rows| rows.trailing_zeros() as u8)
        .collect();
    log_heights[BLAKE3_SLOT] = blake3_chunk_log_heights[0];

    for (i, g) in groups.iter().enumerate() {
        let lde = lde_columns(&group_columns(g), options);
        roots[i] = commit_lde_columns(&lde);
        // Dropped here — peak residency is one group's LDE.
        drop(lde);
    }
    // Then `LFM_BLAKE3`, one chunk at a time: materialize the chunk's group,
    // expand it, commit it, drop both. Peak residency stays one chunk's LDE —
    // which is the whole point of chunking this chip.
    let blake3_chunk_roots: Vec<Commitment> = (0..blake3_chunk_log_heights.len())
        .map(|c| {
            let group = program.blake3_chunk_group(c);
            let lde = lde_columns(&group_columns(&group), options);
            drop(group);
            let root = commit_lde_columns(&lde);
            drop(lde);
            root
        })
        .collect();
    roots[BLAKE3_SLOT] = blake3_chunk_roots[0];
    // Slot 12 (KECCAK_RND) keeps the all-zero sentinel installed above.
    roots[13] = keccak_rc::preprocessed_commitment(options);
    log_heights[13] = keccak_rc::NUM_ROWS.trailing_zeros() as u8;
    roots[14] = bitwise::preprocessed_commitment(options);
    log_heights[14] = bitwise::NUM_ROWS.trailing_zeros() as u8;

    // The families this program uses, and the chunk count that follows from
    // them: zero KECCAK_RND instances when the keccak family is absent, since
    // the chunking policy's floor of one exists only to keep an unused chip
    // present.
    let chip_set = ChipSet::for_program(program);
    let keccak_rnd_chunks = chip_set.keccak_rnd_chunks(
        program
            .chunking
            .chunk_count(program.groups.keccak.real_rows),
    );
    // ★ `blake3_chunk_roots` is NOT mask-gated the way `keccak_rnd_chunks` is,
    // and the asymmetry is real: `KECCAK_RND` commits nothing, so an absent
    // family can drop to zero instances for free, while `LFM_BLAKE3`'s
    // instruction group is COMMITTED whether the family is used or not — slot 11
    // has always carried a root and a height for a program that never
    // compresses. So the chunk lists describe what was committed (never empty)
    // and the mask decides what a proof carries, exactly where it always did:
    // `ChipSet::num_airs` and `LfmAirs::air_refs`.

    let program_id = lfm_program_id(
        &roots,
        &log_heights,
        keccak_rnd_chunks,
        hasher,
        chip_set,
        &blake3_chunk_roots,
        &blake3_chunk_log_heights,
    );
    LfmArtifacts {
        roots,
        log_heights,
        keccak_rnd_chunks,
        blake3_chunk_roots,
        blake3_chunk_log_heights,
        hasher,
        chip_set,
        program_id,
    }
}

/// Resolves a registry entry or fails hard. No fallback path exists or may
/// ever be added.
/// ★ **A duplicate `(kind, blowup_factor)` is an error, not a first-match win.**
///
/// `compute_lfm_registry`'s own doc promises that a second `LFM_HASH` hasher
/// "becomes additional rows, never a silent replacement of these" — but the key
/// here carries no hasher, so `.find()` returned whichever row the generator
/// printed first and the other was unreachable, unnoticed. Since this function
/// is the soundness argument's first premise, the failure mode it left open was
/// a verifier checking a proof against a *different* program's roots than the
/// one whose entry an operator believes is live.
///
/// Rejecting the shape is the cheap half of the fix; the other half is that
/// adding rows stays a deliberate act, which `the_registry_is_six_unambiguous_rows`
/// pins. It returns an `Err` rather than panicking because this runs on the
/// verify path, where an unusable input is a rejected proof.
pub fn resolve(
    kind: LfmProgramKind,
    blowup_factor: u8,
) -> Result<&'static LfmRegistryEntry, LfmRegistryError> {
    let mut matches = LFM_REGISTRY
        .iter()
        .filter(|e| e.kind == kind && e.blowup_factor == blowup_factor);
    let first = matches.next().ok_or(LfmRegistryError::UnknownProgram {
        kind,
        blowup_factor,
    })?;
    let extra = matches.count();
    if extra > 0 {
        return Err(LfmRegistryError::AmbiguousProgram {
            kind,
            blowup_factor,
            rows: extra + 1,
        });
    }
    Ok(first)
}

// =========================================================================
// GENERATED — do not edit by hand. Regenerate with:
//   cargo run --bin compute_lfm_registry --release
// and paste the output below. Drift tests recompute and compare on every PR.
//
// ★ WHICH CONFIGURATION THIS TABLE ASSUMES, and what would move it.
//
// Three axes are BOUND into every digest below, and the fourth stopped being
// free at the P-a flip:
//
//   * `hasher` (the `LFM_HASH` socket permutation) is folded into `program_id`,
//     so two hashers are two program identities. Blessed under
//     `HasherKind::Test`; a second hasher becomes additional ROWS, and `resolve`
//     rejects a duplicate `(kind, blowup_factor)` rather than shadowing one.
//   * `blowup_factor` is a column of the table and half of `resolve`'s key.
//     Blessed at 2, the only registered preset.
//   * ★ The COMMITMENT hash — what `stark`'s Merkle layer builds these roots
//     with, as opposed to what the machine runs — is folded into `program_id`
//     too, since the flip. Blessed under `CommitmentHash::Blake3`, which is the
//     non-`cuda` default. Every root below moves with it, and now so does the
//     name.
//
//     ⚠ **This table therefore describes ONE arm of the `cuda` fork.** A `cuda`
//     build's default is keccak (`stark::config::DefaultStarkHash`), so it
//     commits different roots and folds a different tag, and the six
//     `machine_tests::registry_drift_*` tests fail there — correctly, because a
//     `cuda` build really is a different machine with different program
//     identities. The tests are NOT cfg'd off: the incompatibility is the point,
//     and hiding it would leave a build silently claiming identities it does not
//     produce. It resolves when the fork retires (see `DefaultStarkHash`), not
//     before, and blessing a second table is a decision nobody has taken.
//   * ⚠ `BLAKE3_ROUNDS` (the `blake3-6round` feature) — **the previous note here
//     said this table is round-count-invariant, and the flip ENDED that.** It
//     was true while the roots were keccak: the round count moves `LFM_BLAKE3`'s
//     VALUE columns only (width 3556 → 3076, constraints 897 → 769,
//     interactions 1453 → 1261), never the preprocessed instruction group this
//     table commits for that slot. That separation still holds, and
//     `blake3_chip_tests::the_registry_blessing_is_round_count_invariant` still
//     pins it — read it for what it now asserts, which is about COLUMN COUNTS,
//     not about these bytes.
//
//     What changed is underneath it: these roots are now built BY BLAKE3, so the
//     round count moves the Merkle hash itself and therefore every root here.
//     One table no longer serves two builds. That is why the round count is a
//     compile error rather than a convention — see `stark::config`'s assertion —
//     and it is blessed at six, the shipping arm.
